#include <string.h>

int main(void) {
    char a[16], b[16];
    const char *direcoes[] = {"norte", "leste", "sul", "oeste"};
    int ia = -1, ib = -1;

    if (scanf("%15s %15s", a, b) != 2) return 0;

    for (int i = 0; i < 4; i++) {
        if (strcmp(a, direcoes[i]) == 0) ia = i;
        if (strcmp(b, direcoes[i]) == 0) ib = i;
    }

    int diferenca = ia > ib ? ia - ib : ib - ia;
    int angulo = diferenca * 90;
    if (360 - angulo < angulo) angulo = 360 - angulo;

    printf("%d\n", angulo);
    return 0;
}
